package am.zzws.admin;
import android.content.Context;import android.content.SharedPreferences;import com.google.firebase.messaging.FirebaseMessaging;import org.json.JSONObject;import java.util.UUID;
/** Device/account UUIDs and display permission persist; never passwords or API sessions. */
public final class FirebaseAdapter {
 private static volatile ApiClient client;private static long generation;private static final Object NETWORK=new Object();
 private static SharedPreferences preferences(Context c){return c.getApplicationContext().getSharedPreferences("zzws_push",Context.MODE_PRIVATE);}
 static synchronized String device(Context c){SharedPreferences p=preferences(c);String id=p.getString("device",null);if(id==null){id=UUID.randomUUID().toString();p.edit().putString("device",id).commit();}return id;}
 public static synchronized void attach(Context context,ApiClient api){client=api;if(android.os.Build.VERSION.SDK_INT>=33&&context instanceof android.app.Activity&&context.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)((android.app.Activity)context).requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},5);final long ticket=++generation;final Context c=context.getApplicationContext();String owner=AppSession.user==null?"":AppSession.user.optString("id");SharedPreferences p=preferences(c);SharedPreferences.Editor edit=p.edit().putBoolean("enabled",!owner.isEmpty()).putString("userId",owner);if(!owner.equals(p.getString("userId","")))edit.remove("seen");edit.commit();if(owner.isEmpty())return;FirebaseMessaging.getInstance().setAutoInitEnabled(true);FirebaseMessaging.getInstance().getToken().addOnSuccessListener(token->register(c,token,ticket));}
 static void refresh(Context c,String token){long ticket; synchronized(FirebaseAdapter.class){ticket=generation;}register(c.getApplicationContext(),token,ticket);}
 private static void register(Context c,String token,long ticket){new Thread(()->{synchronized(NETWORK){ApiClient target;synchronized(FirebaseAdapter.class){if(client==null||ticket!=generation||!preferences(c).getBoolean("enabled",false))return;target=client;}try{target.call("POST","me/mobile/register",new JSONObject().put("deviceId",device(c)).put("token",token));}catch(Exception ignored){/* retry on next authenticated attach */}}},"zzws-push-register").start();}
 public static synchronized void detach(Context c,ApiClient api){++generation;client=null;preferences(c).edit().putBoolean("enabled",false).remove("userId").remove("seen").commit();FirebaseMessaging.getInstance().setAutoInitEnabled(false);}
 /** Called by the existing background logout task before clearing the API session. */
 public static void revoke(Context c,ApiClient api){detach(c,api);synchronized(NETWORK){try{api.call("POST","me/mobile/revoke",new JSONObject().put("deviceId",device(c)));}catch(Exception ignored){}}FirebaseMessaging.getInstance().deleteToken();}
 static synchronized boolean accept(Context c,String id,String userId){SharedPreferences p=preferences(c);if(!p.getBoolean("enabled",false)||id==null||!id.matches("[a-fA-F0-9-]{36}")||userId!=null&&(!userId.matches("[a-fA-F0-9-]{36}")||!userId.equals(p.getString("userId",""))))return false;String saved=p.getString("seen","");for(String old:saved.split(","))if(id.equals(old))return false;String next=id+","+saved;if(next.length()>7400)next=next.substring(0,7400);p.edit().putString("seen",next).commit();return true;}
}
